const recordLoginFailure = `-- name: RecordLoginFailure :one
WITH cur AS (
    SELECT CASE WHEN locked_until IS NOT NULL AND locked_until <= now() THEN 1 ELSE failed_logins + 1 END AS n
    FROM users WHERE id = $3 FOR UPDATE
)
UPDATE users SET
    failed_logins = cur.n,
    locked_until = CASE WHEN cur.n >= $1::int THEN now() + make_interval(mins => $2::int)
                        WHEN users.locked_until <= now() THEN NULL
                        ELSE users.locked_until END,
    updated_at = now()
FROM cur
WHERE users.id = $3
RETURNING users.failed_logins, users.locked_until
`

type RecordLoginFailureParams struct {
	MaxFailures int32
	LockMinutes int32
	ID          uuid.UUID
}

type RecordLoginFailureRow struct {
	FailedLogins int32
	LockedUntil  *time.Time
}

// Counts consecutive failures and locks the account for lock_minutes once
// max_failures is reached. An expired lock starts a fresh count.
func (q *Queries) RecordLoginFailure(ctx context.Context, arg RecordLoginFailureParams) (RecordLoginFailureRow, error) {
	row := q.db.QueryRow(ctx, recordLoginFailure, arg.MaxFailures, arg.LockMinutes, arg.ID)
	var i RecordLoginFailureRow
	err := row.Scan(&i.FailedLogins, &i.LockedUntil)
	return i, err
}

